const mapWithSortedArray = (map) => {
  const resultMap = new Map();

  for (const [key, value] of map.entries()) {
    resultMap.set(key, value.sort());
  }

  return resultMap;
};

// Voorbeeldgebruik:
const inputMap = new Map([
  ['a', ['banana', 'apple', 'orange']],
  ['b', ['grape', 'apple']]
]);

const sortedMap = mapWithSortedArray(inputMap);
console.log(sortedMap);
```

